/**
 * The hand-written half of the IPC contract.
 *
 * The error vocabulary and the wire shape are generated from the Rust types
 * (`./generated/bindings.ts`, regenerated by `cargo xtask gen-ipc`); only the
 * mapping from a code to the message keys the UI renders lives here.
 *
 * `normalizeIpcError` is total on purpose: a code from a newer core that this
 * build has no copy for still renders a title and a next action, because a blank
 * error surface is worse than a generic one (docs/ARCHITECTURE.md §15).
 *
 * The wording itself lives in `@peregrine/i18n` (keys `ipc.error.<code>.<part>`),
 * so error copy is translated like every other string.
 */

import type { ErrorCode } from "./generated/bindings.js";

export type { AppError, BuildInfo, ErrorCode } from "./generated/bindings.js";

/** A structured error from the core, as it crosses the IPC boundary. */
export interface IpcError {
  readonly code: ErrorCode;
  readonly message: string;
  readonly detail?: string;
  readonly cause?: string;
  readonly retryable: boolean;
}

/**
 * The copy keys `@peregrine/i18n` actually defines.
 *
 * Each one is the catalogue's own key; the union is literal so a typo here is a
 * compile error rather than a key that silently renders as its own name.
 * `ipc-copy.test.ts` in the desktop app checks every key resolves to a non-empty
 * string, which is what keeps this list in step with the catalogue.
 */
export type IpcErrorMessageKey =
  | "ipc.error.invalid_input.title"
  | "ipc.error.invalid_input.advice"
  | "ipc.error.not_found.title"
  | "ipc.error.not_found.advice"
  | "ipc.error.conflict.title"
  | "ipc.error.conflict.advice"
  | "ipc.error.storage_busy.title"
  | "ipc.error.storage_busy.advice"
  | "ipc.error.storage_corrupt.title"
  | "ipc.error.storage_corrupt.advice"
  | "ipc.error.permission_denied.title"
  | "ipc.error.permission_denied.advice"
  | "ipc.error.disk_full.title"
  | "ipc.error.disk_full.advice"
  | "ipc.error.network.title"
  | "ipc.error.network.advice"
  | "ipc.error.provider_rate_limited.title"
  | "ipc.error.provider_rate_limited.advice"
  | "ipc.error.provider_unavailable.title"
  | "ipc.error.provider_unavailable.advice"
  | "ipc.error.provider_schema_drift.title"
  | "ipc.error.provider_schema_drift.advice"
  | "ipc.error.unsafe_content.title"
  | "ipc.error.unsafe_content.advice"
  | "ipc.error.playback_failed.title"
  | "ipc.error.playback_failed.advice"
  | "ipc.error.device_unavailable.title"
  | "ipc.error.device_unavailable.advice"
  | "ipc.error.cancelled.title"
  | "ipc.error.cancelled.advice"
  | "ipc.error.unsupported.title"
  | "ipc.error.unsupported.advice"
  | "ipc.error.internal.title"
  | "ipc.error.internal.advice";

export interface IpcErrorCopy {
  readonly titleKey: IpcErrorMessageKey;
  readonly adviceKey: IpcErrorMessageKey;
}

// The catalogue keys stay lowercase and keep the names the copy was written
// under, while the wire codes come from the Rust enum, so the two vocabularies
// are mapped once, here. The annotation is `Record<ErrorCode, ...>`, which is
// what makes a variant added to the Rust enum fail to compile here until it has
// copy: that is the R4 test for the promise that no code renders blank.
//
// Every code has copy of its own. `PROVIDER_SCHEMA_DRIFT` and `UNSAFE_CONTENT` used
// to share one entry, which told a user whose metadata went stale that a download
// had been blocked; they are different conditions and now read differently.
const COPY: Readonly<Record<ErrorCode, IpcErrorCopy>> = {
  INVALID_INPUT: {
    titleKey: "ipc.error.invalid_input.title",
    adviceKey: "ipc.error.invalid_input.advice",
  },
  NOT_FOUND: { titleKey: "ipc.error.not_found.title", adviceKey: "ipc.error.not_found.advice" },
  CONFLICT: { titleKey: "ipc.error.conflict.title", adviceKey: "ipc.error.conflict.advice" },
  STORAGE_BUSY: {
    titleKey: "ipc.error.storage_busy.title",
    adviceKey: "ipc.error.storage_busy.advice",
  },
  STORAGE_CORRUPT: {
    titleKey: "ipc.error.storage_corrupt.title",
    adviceKey: "ipc.error.storage_corrupt.advice",
  },
  PERMISSION_DENIED: {
    titleKey: "ipc.error.permission_denied.title",
    adviceKey: "ipc.error.permission_denied.advice",
  },
  DISK_FULL: { titleKey: "ipc.error.disk_full.title", adviceKey: "ipc.error.disk_full.advice" },
  NETWORK: { titleKey: "ipc.error.network.title", adviceKey: "ipc.error.network.advice" },
  PROVIDER_RATE_LIMITED: {
    titleKey: "ipc.error.provider_rate_limited.title",
    adviceKey: "ipc.error.provider_rate_limited.advice",
  },
  PROVIDER_UNAVAILABLE: {
    titleKey: "ipc.error.provider_unavailable.title",
    adviceKey: "ipc.error.provider_unavailable.advice",
  },
  PROVIDER_SCHEMA_DRIFT: {
    titleKey: "ipc.error.provider_schema_drift.title",
    adviceKey: "ipc.error.provider_schema_drift.advice",
  },
  UNSAFE_CONTENT: {
    titleKey: "ipc.error.unsafe_content.title",
    adviceKey: "ipc.error.unsafe_content.advice",
  },
  PLAYBACK_FAILED: {
    titleKey: "ipc.error.playback_failed.title",
    adviceKey: "ipc.error.playback_failed.advice",
  },
  DEVICE_UNAVAILABLE: {
    titleKey: "ipc.error.device_unavailable.title",
    adviceKey: "ipc.error.device_unavailable.advice",
  },
  CANCELLED: { titleKey: "ipc.error.cancelled.title", adviceKey: "ipc.error.cancelled.advice" },
  UNSUPPORTED: {
    titleKey: "ipc.error.unsupported.title",
    adviceKey: "ipc.error.unsupported.advice",
  },
  INTERNAL: { titleKey: "ipc.error.internal.title", adviceKey: "ipc.error.internal.advice" },
};

/** The copy mapping, exported for callers that need it for a specific code. */
export const IPC_ERROR_COPY: Readonly<Record<ErrorCode, IpcErrorCopy>> = COPY;

/**
 * The codes this build has copy for, derived from the table so the wire
 * vocabulary has exactly one definition.
 */
export const IPC_ERROR_CODES: readonly ErrorCode[] = Object.keys(COPY) as ErrorCode[];

/** The copy keys for an error, falling back to the generic inside-Peregrine copy. */
export function describeIpcError(error: IpcError): IpcErrorCopy {
  // `COPY` is total over the generated union; the fallback covers a code sent by
  // a newer core, which the type cannot describe.
  return isIpcErrorCode(error.code) ? COPY[error.code] : COPY.INTERNAL;
}

/** True when `value` is one of the codes this build knows copy for. */
export function isIpcErrorCode(value: unknown): value is ErrorCode {
  return typeof value === "string" && Object.hasOwn(COPY, value);
}

/**
 * Turns anything a call site can throw into a structured error.
 *
 * Nothing is stringified: an arbitrary thrown value could be a proxy, a cyclic
 * object, or a provider payload, and `detail`/`cause` are only kept when the core
 * sent strings, so foreign objects never reach the screen.
 */
export function normalizeIpcError(caught: unknown): IpcError {
  if (isRecord(caught)) {
    // An error handler that throws while describing an error takes the surrounding
    // tree down with it, so a throwing accessor is treated as an unknown error.
    try {
      return fromRecord(caught);
    } catch {
      return genericError();
    }
  }
  if (typeof caught === "string" && caught.trim() !== "") {
    return { code: "INTERNAL", message: caught, retryable: false };
  }
  return genericError();
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function fromRecord(caught: Record<string, unknown>): IpcError {
  const code = caught["code"];
  const message = stringOrUndefined(caught["message"]);
  const detail = stringOrUndefined(caught["detail"]);
  const cause = stringOrUndefined(caught["cause"]);
  return {
    code: isIpcErrorCode(code) ? code : "INTERNAL",
    message: message ?? GENERIC_MESSAGE,
    // Absent or non-boolean means the core did not offer a retry; never invent one.
    retryable: caught["retryable"] === true,
    // `exactOptionalPropertyTypes` distinguishes "absent" from "undefined", and a
    // consumer can then treat a missing `detail` as "the core sent none".
    ...(detail === undefined ? {} : { detail }),
    ...(cause === undefined ? {} : { cause }),
  };
}

/**
 * Last-resort message for an error the core did not describe. It is deliberately
 * not user-facing copy: the UI renders `ipc.error.internal.*` instead.
 */
export const GENERIC_MESSAGE = "the core returned an error with no message";

function genericError(): IpcError {
  return { code: "INTERNAL", message: GENERIC_MESSAGE, retryable: false };
}

function stringOrUndefined(value: unknown): string | undefined {
  return typeof value === "string" && value !== "" ? value : undefined;
}
